package com.example.bandlink.controller; import com.example.bandlink.service.PostService; import com.example.bandlink.service.AccountDeletionService; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/posts") public class AdminPostController{private final PostService posts;private final AccountDeletionService accountDeletion;public AdminPostController(PostService p,AccountDeletionService accountDeletion){posts=p;this.accountDeletion=accountDeletion;}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){posts.adminDelete(id);return ResponseEntity.noContent().build();}@DeleteMapping("/{id}/permanent") public ResponseEntity<Void> deletePermanently(@PathVariable Long id){accountDeletion.deletePost(id);return ResponseEntity.noContent().build();}}
